using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Users.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.Users.Commands.UpdateUser;public sealed class UpdateUserCommandHandler(IUserRepository repository,IRoleRepository roles,IApplicationDbContext db):IRequestHandler<UpdateUserCommand,Result<UserDto>>{public async Task<Result<UserDto>>Handle(UpdateUserCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.Id,cancellationToken);if(e is null)return Result.Failure<UserDto>(UserErrors.NotFound);if(await roles.FindByIdAsync(request.RoleId,cancellationToken)is null)return Result.Failure<UserDto>(UserErrors.RoleNotFound);if((request.Email is not null&&await repository.EmailExistsAsync(request.Email,request.Id,cancellationToken))||(request.PhoneNumber is not null&&await repository.PhoneExistsAsync(request.PhoneNumber,request.Id,cancellationToken)))return Result.Failure<UserDto>(UserErrors.DuplicateContact);e.UpdateProfile(request.FullName,request.Email,request.PhoneNumber);e.ChangeRole(request.RoleId);if(request.IsActive)e.Activate();else e.Deactivate();await db.SaveChangesAsync(cancellationToken);return Result.Success(UserDto.FromEntity(e));}}
